"""
Generador de flyers para Instagram Stories (diseño Onda Uno) a partir de un link de noticia.
Uso:  pip install flask requests beautifulsoup4 pillow
      python app.py   ->  se abre http://localhost:5000
Archivos junto al programa: logo.png (logo) y carpeta fonts/ (tipografias).
Si ponés un logo.png al lado del .exe, se usa ese en lugar del incluido.
"""
import io, os, sys, re, base64, math, socket, ipaddress, random
from urllib.parse import urljoin, urlparse

import requests
from bs4 import BeautifulSoup
from flask import Flask, request, jsonify, render_template_string
from PIL import Image, ImageDraw, ImageFont, ImageFilter

W, H = 1080, 1920
GREEN, GREEN_L = (45, 194, 102), (110, 232, 80)
WHITE, GREY = (255, 255, 255), (190, 197, 203)
UA = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36"}
DEFAULT_TAG = "TRES ARROYOS • LOCALES"
VERSION = "web v2 · 5 diseños"
ACCESS_CODE = os.environ.get("ACCESS_CODE", "")  # opcional: si la definís en Render, la app pide ese código

BUNDLE = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
EXE_DIR = os.path.dirname(sys.executable) if getattr(sys, "frozen", False) else BUNDLE


def asset(*parts):
    for base in (EXE_DIR, BUNDLE):
        p = os.path.join(base, *parts)
        if os.path.exists(p):
            return p


def font(name, size, fallbacks=()):
    if name in FONTS_B64 and not asset("fonts", name):
        return ImageFont.truetype(io.BytesIO(base64.b64decode(FONTS_B64[name])), size)
    for p in [asset("fonts", name), *fallbacks]:
        try:
            if p:
                return ImageFont.truetype(p, size)
        except OSError:
            pass
    return ImageFont.load_default()


def headline_font(s):
    return font("Anton-Regular.ttf", s, ["C:/Windows/Fonts/impact.ttf", "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"])


def bold_font(s):
    return font("Carlito-Bold.ttf", s, ["C:/Windows/Fonts/calibrib.ttf", "C:/Windows/Fonts/arialbd.ttf"])


def italic_font(s):
    return font("Carlito-Italic.ttf", s, ["C:/Windows/Fonts/calibrii.ttf", "C:/Windows/Fonts/ariali.ttf"])


# ---------------------------------------------------------------- scraping
def meta(soup, *names):
    for n in names:
        t = soup.find("meta", attrs={"property": n}) or soup.find("meta", attrs={"name": n})
        if t and t.get("content"):
            return t["content"].strip()


def check_url(url):
    host = urlparse(url).hostname
    if not host or urlparse(url).scheme not in ("http", "https"):
        raise ValueError("Link no válido.")
    for info in socket.getaddrinfo(host, None):
        ip = ipaddress.ip_address(info[4][0])
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved:
            raise ValueError("Ese link no está permitido.")


def scrape(url):
    check_url(url)
    r = requests.get(url, headers=UA, timeout=15)
    r.raise_for_status()
    soup = BeautifulSoup(r.text, "html.parser")
    title = meta(soup, "og:title", "twitter:title") or (soup.title.get_text().strip() if soup.title else "")
    title = re.sub(r"\s+[|\-–—]\s+[^|\-–—]{2,40}$", "", title).strip()
    desc = meta(soup, "og:description", "twitter:description", "description") or ""
    img_url = meta(soup, "og:image", "twitter:image")
    if not img_url:
        raise ValueError("No encontré una imagen en esa página.")
    check_url(urljoin(url, img_url))
    ir = requests.get(urljoin(url, img_url), headers=UA, timeout=15)
    ir.raise_for_status()
    return title, desc, Image.open(io.BytesIO(ir.content)).convert("RGB")


# ---------------------------------------------------------------- dibujo
def cover(img, w, h):
    s = max(w / img.width, h / img.height)
    img = img.resize((int(img.width * s) + 1, int(img.height * s) + 1), Image.LANCZOS)
    x, y = (img.width - w) // 2, (img.height - h) // 2
    return img.crop((x, y, x + w, y + h))


def wrap(draw, text, f, max_w):
    lines, cur = [], ""
    for word in text.split():
        t = (cur + " " + word).strip()
        if draw.textlength(t, font=f) <= max_w or not cur:
            cur = t
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def background():
    bg = Image.new("RGB", (W, H))
    d = ImageDraw.Draw(bg)
    for y in range(H):
        t = y / H
        d.line([(0, y), (W, y)], fill=(int(13 + 4 * t), int(21 + 5 * t), int(25 + 6 * t)))
    ov = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    o = ImageDraw.Draw(ov)
    for x in range(0, W, 72):
        o.line([(x, 0), (x, H)], fill=(255, 255, 255, 7))
    for y in range(0, H, 72):
        o.line([(0, y), (W, y)], fill=(255, 255, 255, 7))
    for cx, cy in ((W + 40, 40), (-40, H - 40)):          # líneas topográficas
        for i, r in enumerate(range(110, 560, 26)):
            k = 1 + 0.08 * math.sin(i)
            o.ellipse([cx - r * 1.25 * k, cy - r * 0.8, cx + r * 1.25 * k, cy + r * 0.8],
                      outline=GREEN + (46,), width=2)
    smoke = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    s = ImageDraw.Draw(smoke)
    for box in ((-200, 950, 250, 1250), (830, 900, 1300, 1250), (250, 1120, 850, 1300)):
        s.ellipse(box, fill=(150, 160, 160, 80))
    smoke = smoke.filter(ImageFilter.GaussianBlur(60))
    glow_l = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    g = ImageDraw.Draw(glow_l)
    for box in ((700, -300, 1400, 380), (-400, 1500, 500, 2200), (-300, -250, 400, 300)):
        g.ellipse(box, fill=GREEN + (40,))
    glow_l = glow_l.filter(ImageFilter.GaussianBlur(120))
    bg = Image.alpha_composite(bg.convert("RGBA"), glow_l)
    bg = Image.alpha_composite(bg, ov)
    return Image.alpha_composite(bg, smoke)


def glow(base, draw_fn, color, blur=14, strength=1.0):
    layer = Image.new("RGBA", base.size, (0, 0, 0, 0))
    draw_fn(ImageDraw.Draw(layer), color + (int(255 * strength),))
    blurred = layer.filter(ImageFilter.GaussianBlur(blur))
    base.alpha_composite(blurred)
    draw_fn(ImageDraw.Draw(layer := Image.new("RGBA", base.size, (0, 0, 0, 0))), color + (255,))
    base.alpha_composite(layer)


def draw_logo(canvas):
    p = asset("logo.png")
    if True:
        logo = Image.open(p if p else io.BytesIO(base64.b64decode(LOGO_B64))).convert("RGBA")
        s = 330 / logo.width
        logo = logo.resize((330, int(logo.height * s)), Image.LANCZOS)
        canvas.alpha_composite(logo, ((W - logo.width) // 2, 90))


def build_neon(title, desc, photo, tag, highlight, source):
    canvas = background()
    draw_logo(canvas)
    d = ImageDraw.Draw(canvas)

    # divisor superior
    d.line([(99, 314), (981, 314)], fill=(70, 80, 84, 255), width=2)
    d.rounded_rectangle([452, 310, 628, 318], radius=4, fill=GREEN + (255,))

    # marco neón (esquina superior derecha e inferior izquierda)
    def frame(dd, col):
        r, w = 40, 5
        # esquina superior derecha
        dd.line([(660, 400), (1004 - r, 400)], fill=col, width=w)
        dd.arc([1004 - 2 * r, 400, 1004, 400 + 2 * r], 270, 360, fill=col, width=w)
        dd.line([(1004, 400 + r), (1004, 760)], fill=col, width=w)
        # esquina inferior izquierda
        dd.line([(76, 760), (76, 1112 - r)], fill=col, width=w)
        dd.arc([76, 1112 - 2 * r, 76 + 2 * r, 1112], 90, 180, fill=col, width=w)
        dd.line([(76 + r, 1112), (440, 1112)], fill=col, width=w)
    glow(canvas, frame, GREEN_L, blur=14)
    glow(canvas, frame, GREEN_L, blur=5, strength=0.6)

    # foto con esquinas redondeadas
    px, py, pw, ph = 99, 421, 882, 669
    ph_img = cover(photo, pw, ph).convert("RGBA")
    mask = Image.new("L", (pw, ph), 0)
    ImageDraw.Draw(mask).rounded_rectangle([0, 0, pw - 1, ph - 1], radius=28, fill=255)
    canvas.paste(ph_img, (px, py), mask)
    d = ImageDraw.Draw(canvas)
    d.rounded_rectangle([px, py, px + pw - 1, py + ph - 1], radius=28, outline=(255, 255, 255, 45), width=2)

    # etiqueta (pill)
    if tag:
        f = bold_font(29)
        tw = d.textlength(tag.upper().replace("•", "·"), font=f)
        x1, x0, y0 = 954, 954 - tw - 64, 1050
        pill = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        pd = ImageDraw.Draw(pill)
        pd.rounded_rectangle([x0, y0, x1, y0 + 54], radius=27, fill=(135, 140, 142, 175), outline=(225, 228, 228, 120), width=2)
        canvas.alpha_composite(pill)
        ImageDraw.Draw(canvas).text(((x0 + x1) / 2, y0 + 27), tag.upper().replace("•", "·"), font=f, fill=(240, 243, 243), anchor="mm")

    # titular: palabra destacada (verde) + resto (blanco)
    title = " ".join(title.split()).upper()
    hl = " ".join(highlight.split()).upper() if highlight else ""
    if hl and title.startswith(hl):
        rest = title[len(hl):].strip()
    elif hl:
        hl, rest = hl, title
    else:
        parts = title.split(" ", 1)
        hl, rest = parts[0], (parts[1] if len(parts) > 1 else "")
    probe = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    maxw, top, budget = 880, 1200, 335
    for size in range(104, 51, -2):
        f = headline_font(size)
        lines = ([hl] if hl else []) + (wrap(probe, rest, f, maxw) if rest else [])
        lh = int(size * 1.13)
        if len(lines) * lh <= budget and all(probe.textlength(l, font=f) <= maxw for l in lines):
            break
    n_hl = 1 if hl else 0
    y = top

    def hl_text(dd, col):
        dd.text((W / 2, top + lh / 2), hl, font=f, fill=col, anchor="mm")
    if hl:
        glow(canvas, hl_text, GREEN_L, blur=16, strength=0.55)
    d = ImageDraw.Draw(canvas)
    for i, ln in enumerate(lines):
        cy = y + lh / 2
        d.text((W / 2, cy), ln, font=f, fill=GREEN_L if i < n_hl else WHITE, anchor="mm")
        y += lh

    # bajada
    if desc:
        desc = " ".join(desc.split())
        if len(desc) > 150:
            desc = desc[:147].rsplit(" ", 1)[0] + "…"
        fi = italic_font(36)
        dl = wrap(d, desc, fi, 780)[:3]
        yy = y + 22
        for ln in dl:
            d.text((W / 2, yy + 22), ln, font=fi, fill=GREY, anchor="mm")
            yy += 52

    # divisor inferior
    d.line([(99, 1724), (981, 1724)], fill=(70, 80, 84, 255), width=2)
    d.rounded_rectangle([457, 1720, 623, 1728], radius=4, fill=GREEN + (255,))

    # pie: globo + dominio
    fs = bold_font(36)
    dom = source
    tw = d.textlength(dom, font=fs)
    gx, gy = 398, 1805
    d.ellipse([gx - 17, gy - 17, gx + 17, gy + 17], outline=GREEN, width=3)
    d.ellipse([gx - 7, gy - 17, gx + 7, gy + 17], outline=GREEN, width=2)
    d.line([(gx - 17, gy), (gx + 17, gy)], fill=GREEN, width=2)
    d.text((gx + 32, gy), dom, font=fs, fill=(225, 230, 230), anchor="lm")

    # pie: deslizá
    cx = 800
    for off in (0, 14):
        d.line([(cx - 15, gy + 2 - off), (cx, gy - 12 - off), (cx + 15, gy + 2 - off)], fill=GREEN, width=4, joint="curve")
    f2 = bold_font(23)
    d.text((cx + 40, gy - 14), "DESLIZÁ PARA", font=f2, fill=GREEN, anchor="lm")
    d.text((cx + 40, gy + 14), "LEER LA NOTA", font=f2, fill=GREEN, anchor="lm")
    return canvas.convert("RGB")

# ---------------------------------------------------------------- 5 diseños nuevos
_logo_cache = {}


def get_logo(dark=False, width=330):
    key = (dark, width)
    if key not in _logo_cache:
        p = asset("logo.png")
        lg = Image.open(p if p else io.BytesIO(base64.b64decode(LOGO_B64))).convert("RGBA")
        if dark:  # texto "ONDA UNO" en oscuro para fondos claros (la parte verde se conserva)
            px = lg.load()
            for y in range(int(lg.height * 0.5), lg.height):
                for x in range(lg.width):
                    r, g, b, a = px[x, y]
                    if a and g - r < 35:
                        px[x, y] = (28, 34, 38, a)
        lg = lg.resize((width, int(lg.height * width / lg.width)), Image.LANCZOS)
        _logo_cache[key] = lg
    return _logo_cache[key]


def fit_title(title, fontfn, maxw, budget, sizes, lh=1.2):
    probe = ImageDraw.Draw(Image.new("RGB", (10, 10)))
    title = " ".join(title.split())
    for size in sizes:
        f = fontfn(size)
        lines = wrap(probe, title, f, maxw)
        if len(lines) * int(size * lh) <= budget and all(probe.textlength(l, font=f) <= maxw for l in lines):
            return f, lines, int(size * lh)
    n = max(1, budget // int(sizes[-1] * lh))
    lines = lines[:n]
    lines[-1] = lines[-1].rstrip(".,; ") + "…"
    return f, lines, int(sizes[-1] * lh)


def draw_title(d, lines, f, lh, x, y_top, y_bottom, fill):
    y = y_top + (y_bottom - y_top - len(lines) * lh) / 2
    for ln in lines:
        d.text((x, y + lh / 2), ln, font=f, fill=fill, anchor="lm")
        y += lh


def footer(canvas, y0, bg, fg, sub, arrow, source):
    d = ImageDraw.Draw(canvas)
    if bg:
        d.rectangle([0, y0, W, H], fill=bg)
    cx, ay = W // 2, y0 + 85
    d.line([(cx, ay + 26), (cx, ay - 20)], fill=arrow, width=5)
    d.line([(cx - 18, ay - 2), (cx, ay - 20), (cx + 18, ay - 2)], fill=arrow, width=5, joint="curve")
    f = bold_font(38)
    d.text((cx, y0 + 165), "Deslizá hacia arriba", font=f, fill=fg, anchor="mm")
    d.text((cx, y0 + 216), "para leer la nota completa", font=f, fill=fg, anchor="mm")
    d.text((cx, y0 + 300), source, font=bold_font(32), fill=sub, anchor="mm")


def put_photo(canvas, photo, box):
    x0, y0, x1, y1 = box
    canvas.paste(cover(photo, x1 - x0, y1 - y0).convert("RGBA"), (x0, y0))


def d_claro(title, desc, photo, tag, hl, source):
    c = Image.new("RGBA", (W, H), (248, 242, 233, 255))
    c.alpha_composite(get_logo(True, 320), ((W - 320) // 2, 95))
    f, lines, lh = fit_title(title, bold_font, 880, 300, range(76, 47, -2))
    d = ImageDraw.Draw(c)
    draw_title(d, lines, f, lh, 100, 470, 770, (28, 32, 36))
    d.line([(0, 790), (W, 790)], fill=(214, 196, 170), width=3)
    put_photo(c, photo, (0, 800, W, 1540))
    footer(c, 1545, (26, 31, 35), (240, 243, 243), (150, 158, 160), (45, 194, 102), source)
    return c


def d_oscuro(title, desc, photo, tag, hl, source):
    bg = (20, 24, 28)
    c = Image.new("RGBA", (W, H), bg + (255,))
    c.alpha_composite(get_logo(False, 320), ((W - 320) // 2, 95))
    f, lines, lh = fit_title(title, bold_font, 880, 290, range(76, 47, -2))
    d = ImageDraw.Draw(c)
    draw_title(d, lines, f, lh, 100, 470, 760, WHITE)
    d.line([(100, 790), (980, 790)], fill=(34, 139, 76), width=4)
    d.rectangle([88, 832, 992, 1492], outline=(60, 68, 74), width=2)
    put_photo(c, photo, (100, 844, 980, 1480))
    footer(c, 1545, None, (240, 243, 243), (150, 158, 160), (45, 194, 102), source)
    return c


def d_bloques(title, desc, photo, tag, hl, source):
    VERDE = (24, 128, 60)
    c = Image.new("RGBA", (W, H), (231, 238, 231, 255))
    c.alpha_composite(get_logo(True, 320), ((W - 320) // 2, 95))
    d = ImageDraw.Draw(c)
    d.rectangle([0, 400, W, 850], fill=WHITE)
    f, lines, lh = fit_title(title, bold_font, 880, 360, range(76, 47, -2))
    draw_title(d, lines, f, lh, 100, 400, 850, (28, 32, 36))
    if tag:
        ft = bold_font(24)
        t = tag.upper().replace("•", "·")
        tw = d.textlength(t, font=ft)
        d.rectangle([100, 880, 100 + tw + 44, 930], fill=VERDE)
        d.text((122, 905), t, font=ft, fill=WHITE, anchor="lm")
    d.rectangle([100, 960, 980, 1520], outline=VERDE, width=3)
    put_photo(c, photo, (124, 984, 956, 1496))
    footer(c, 1560, VERDE, WHITE, (205, 232, 214), WHITE, source)
    return c


def d_prensa(title, desc, photo, tag, hl, source):
    c = Image.new("RGBA", (W, H), (255, 255, 255, 255))
    c.alpha_composite(get_logo(True, 320), ((W - 320) // 2, 95))
    d = ImageDraw.Draw(c)
    d.line([(100, 385), (980, 385)], fill=(200, 200, 200), width=2)
    f, lines, lh = fit_title(title, headline_font, 880, 380, range(104, 55, -2), lh=1.1)
    draw_title(d, lines, f, lh, 100, 420, 800, (17, 17, 17))
    d.line([(100, 820), (980, 820)], fill=(200, 200, 200), width=2)
    put_photo(c, photo, (100, 850, 980, 1400))
    d.line([(100, 1430), (980, 1430)], fill=(200, 200, 200), width=2)
    footer(c, 1545, (26, 31, 35), (240, 243, 243), (150, 158, 160), WHITE, source)
    return c


def d_foto(title, desc, photo, tag, hl, source):
    bg = (20, 24, 28)
    c = Image.new("RGBA", (W, H), bg + (255,))
    put_photo(c, photo, (0, 0, W, 1560))
    ov = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    od = ImageDraw.Draw(ov)
    for y in range(780, 1561):
        od.line([(0, y), (W, y)], fill=bg + (int(255 * ((y - 780) / 780) ** 1.15),))
    for y in range(0, 420):
        od.line([(0, y), (W, y)], fill=(0, 0, 0, int(150 * (1 - y / 420))))
    c.alpha_composite(ov)
    c.alpha_composite(get_logo(False, 320), ((W - 320) // 2, 95))
    f, lines, lh = fit_title(title, bold_font, 880, 380, range(76, 47, -2))
    d = ImageDraw.Draw(c)
    draw_title(d, lines, f, lh, 100, 1500 - 380, 1500, WHITE)
    footer(c, 1560, None, (240, 243, 243), (150, 158, 160), (45, 194, 102), source)
    return c


DESIGNS = {"claro": d_claro, "oscuro": d_oscuro, "bloques": d_bloques, "prensa": d_prensa, "foto": d_foto, "neon": build_neon}
NOMBRES = {"claro": "Minimalista claro", "oscuro": "Oscuro sobrio", "bloques": "Bloques con verde",
           "prensa": "Estilo prensa", "foto": "Fotográfico editorial", "neon": "Neón"}
_last = [None]


def build_flyer(title, desc, photo, tag, highlight, source, design="azar"):
    if design not in DESIGNS:   # al azar entre los 5 patrones, sin repetir el anterior
        design = random.choice([k for k in ("claro", "oscuro", "bloques", "prensa", "foto") if k != _last[0]])
    _last[0] = design
    return DESIGNS[design](title, desc, photo, tag, highlight, source).convert("RGB"), design


